def transform(grid):
    def solve_rows(matrix):
        result = []
        for row in matrix:
            n = len(row)
            zeros = row.count(0)
            if zeros > 3 and row[0] == 0:
                tail = row[zeros:]
                result.append([0] + tail + [7] * (n - 1 - len(tail)))
            elif zeros >= 3 and row[-1] == 0:
                result.append(row[::-1])
            else:
                result.append(row[:])
        return result

    def has_long_zero_row(matrix):
        return any(max((len(part) for part in ''.join('0' if x == 0 else '1' for x in row).split('1')), default=0) >= 3 for row in matrix)

    if has_long_zero_row(grid):
        return solve_rows(grid)
    transposed = [list(col) for col in zip(*grid)]
    solved = solve_rows(transposed)
    return [list(row) for row in zip(*solved)]
